package main

// Node mirrors the structure of gopkg.in/yaml.v3's yaml.Node.
// All codecs (yaml/json/xml/props/csv/...) parse into and encode from
// a tree of *Node. A parsed stream is a sequence of document Nodes
// (Kind == DocumentNode), each with exactly one child in Content[0]
// (which may be a null scalar for empty documents).

type Kind int

const (
	DocumentNode Kind = 1 << iota
	SequenceNode
	MappingNode
	ScalarNode
	AliasNode
)

type Style int

const (
	TaggedStyle Style = 1 << iota
	DoubleQuotedStyle
	SingleQuotedStyle
	LiteralStyle
	FoldedStyle
	FlowStyle
)

type Node struct {
	Kind    Kind
	Style   Style
	Tag     string // e.g. "!!str", "!!int", "!!map", "!custom"
	Value   string // scalar value; for AliasNode the alias name
	Anchor  string
	Alias   *Node   // set for AliasNode
	Content []*Node // Mapping: key,value interleaved. Sequence: items. Document: single child.

	HeadComment string // comment lines above the node, without '#', space separated lines joined by \n
	LineComment string // comment on the same line
	FootComment string // comment lines following the node

	Line   int // 1-based line where node starts (best effort)
	Column int

	// internal book-keeping (not part of yaml.v3 semantics)
	DocSeparator bool // document was preceded by '---' in its source stream
	DocIndex     int  // index of source document in the input stream
}

// Document wraps n in a document node.
func Document(n *Node) *Node {
	d := &Node{Kind: DocumentNode, Tag: "!!map"}
	if n == nil {
		n = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	d.Content = []*Node{n}
	return d
}

func Scalar(tag, value string) *Node {
	return &Node{Kind: ScalarNode, Tag: tag, Value: value}
}

func Str(value string) *Node  { return Scalar("!!str", value) }
func Int(value string) *Node  { return Scalar("!!int", value) }
func Null() *Node             { return Scalar("!!null", "") }
func Bool(value string) *Node { return Scalar("!!bool", value) }

func Mapping(style Style) *Node {
	return &Node{Kind: MappingNode, Tag: "!!map", Style: style}
}

func Sequence(style Style) *Node {
	return &Node{Kind: SequenceNode, Tag: "!!seq", Style: style}
}

// Unwrap returns the innermost child for document nodes.
func (n *Node) Unwrap() *Node {
	if n != nil && n.Kind == DocumentNode && len(n.Content) > 0 {
		return n.Content[0]
	}
	return n
}

// MapKeys returns the keys of a mapping node.
func (n *Node) MapKeys() []*Node {
	n = n.Unwrap()
	if n == nil || n.Kind != MappingNode {
		return nil
	}
	keys := make([]*Node, 0, len(n.Content)/2)
	for i := 0; i < len(n.Content); i += 2 {
		keys = append(keys, n.Content[i])
	}
	return keys
}

// MapValues returns the values of a mapping node.
func (n *Node) MapValues() []*Node {
	n = n.Unwrap()
	if n == nil || n.Kind != MappingNode {
		return nil
	}
	vals := make([]*Node, 0, len(n.Content)/2)
	for i := 1; i < len(n.Content); i += 2 {
		vals = append(vals, n.Content[i])
	}
	return vals
}

// MapGet returns the value for key, or nil.
func (n *Node) MapGet(key string) *Node {
	n = n.Unwrap()
	if n == nil || n.Kind != MappingNode {
		return nil
	}
	for i := 0; i < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

// MapSet sets (or appends) a key/value pair on a mapping node.
func (n *Node) MapSet(key string, value *Node) {
	if n.Kind != MappingNode {
		return
	}
	for i := 0; i < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			n.Content[i+1] = value
			return
		}
	}
	n.Content = append(n.Content, Str(key), value)
}

// DeepCopy clones the node tree (aliases are preserved as references).
func (n *Node) DeepCopy() *Node {
	if n == nil {
		return nil
	}
	c := *n
	if n.Kind != AliasNode {
		c.Content = make([]*Node, len(n.Content))
		for i, ch := range n.Content {
			c.Content[i] = ch.DeepCopy()
		}
	}
	return &c
}

