args.content:
package yq

import (
	"fmt"
	"strings"
)

// A from-scratch YAML (1.2 core-schema) parser producing *Node trees with
// comment/anchor/tag/style fidelity approximating gopkg.in/yaml.v3.

type yamlLine struct {
	text string // raw line without trailing \n (and without trailing \r)
	num  int    // 1-based
}

// YamlParseError mimics yaml.v3 error strings where feasible.
type YamlParseError struct{ Msg string }

func (e *YamlParseError) Error() string { return "yaml: " + e.Msg }

func yamlErr(line int, format string, args ...interface{}) error {
	return &YamlParseError{Msg: fmt.Sprintf("line %d: %s", line, fmt.Sprintf(format, args...))}
}

type yamlParser struct {
	lines   []yamlLine
	pos     int
	anchors map[string]*Node
	docIdx  int
}

// ParseYAML parses a whole stream into document nodes.
func ParseYAML(data []byte) ([]*Node, error) {
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	raw := strings.Split(s, "\n")
	// drop the artificial last empty line from trailing \n
	if len(raw) > 0 && raw[len(raw)-1] == "" {
		raw = raw[:len(raw)-1]
	}
	lines := make([]yamlLine, len(raw))
	for i, l := range raw {
		lines[i] = yamlLine{l, i + 1}
	}
	p := &yamlParser{lines: lines, anchors: map[string]*Node{}}
	var docs []*Node
	for {
		doc, err := p.parseDocument()
		if err != nil {
			return nil, err
		}
		if doc == nil {
			break
		}
		docs = append(docs, doc)
	}
	if len(docs) == 0 {
		// empty stream -> single empty document
		d := &Node{Kind: DocumentNode, Tag: "!!null", Content: []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}}
		docs = append(docs, d)
	}
	for i, d := range docs {
		d.DocIndex = i
	}
	return docs, nil
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

// peek returns the current line or nil at EOF.
func (p *yamlParser) peek() *yamlLine {
	if p.pos >= len(p.lines) {
		return nil
	}
	return &p.lines[p.pos]
}

// skipBlank advances over blank lines (not comments).
func (p *yamlParser) skipBlank() {
	for p.pos < len(p.lines) && isBlank(p.lines[p.pos].text) {
		p.pos++
	}
}

// nextSignificant returns index of next non-blank, non-comment line >= pos.
func (p *yamlParser) nextSignificant(from int) int {
	i := from
	for i < len(p.lines) {
		t := strings.TrimSpace(p.lines[i].text)
		if t != "" && !strings.HasPrefix(t, "#") {
			return i
		}
		i++
	}
	return i
}

type pendingComments struct {
	lines []string // each entry: comment text (after #) or "" for blank separator
}

func (pc *pendingComments) add(raw string) {
	// raw is full line; strip leading spaces and '#'
	t := strings.TrimLeft(raw, " ")
	if strings.HasPrefix(t, "#") {
		t = t[1:]
		if strings.HasPrefix(t, " ") {
			t = t[1:]
		}
		pc.lines = append(pc.lines, t)
	}
}

func (pc *pendingComments) blank() {
	if len(pc.lines) > 0 {
		pc.lines = append(pc.lines, "")
	}
}

func (pc *pendingComments) String() string { return strings.Join(pc.lines, "\n") }
func (pc *pendingComments) empty() bool    { return len(pc.lines) == 0 }
func (pc *pendingComments) reset()         { pc.lines = nil }

// parseDocument parses one document; returns nil at EOF.
func (p *yamlParser) parseDocument() (*Node, error) {
	var head pendingComments
	// consume blank lines, comments, directives
	sawAny := false
	for {
		l := p.peek()
		if l == nil {
			if !sawAny && head.empty() {
				return nil, nil
			}
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			head.blank()
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			head.add(l.text)
			p.pos++
			sawAny = true
			continue
		}
		if strings.HasPrefix(t, "%") {
			// directive: keep as head-comment-like text on document
			head.lines = append(head.lines, directiveMarker+t)
			p.pos++
			sawAny = true
			continue
		}
		break
	}

	l := p.peek()
	if l == nil {
		if !sawAny {
			return nil, nil
		}
		d := &Node{Kind: DocumentNode, Tag: "!!null", HeadComment: head.String(),
			Content: []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}}
		return d, nil
	}

	doc := &Node{Kind: DocumentNode}
	doc.HeadComment = head.String()
	doc.Line = l.num

	trimmed := strings.TrimSpace(l.text)
	if trimmed == "..." {
		p.pos++
		// empty doc ended by ...
		doc.Tag = "!!null"
		doc.Content = []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}
		doc.DocSeparator = p.docIdx > 0
		p.docIdx++
		return doc, nil
	}

	var content *Node
	var err error
	if strings.HasPrefix(trimmed, "---") {
		rest := strings.TrimPrefix(trimmed, "---")
		if rest != "" && rest[0] != ' ' && rest[0] != '\t' && rest[0] != '#' {
			return nil, yamlErr(l.num, "did not find expected comment or line break")
		}
		doc.DocSeparator = true
		baseIndent := indentOf(l.text)
		rest = strings.TrimSpace(strings.SplitN(rest, "#", 2)[0])
		p.pos++
		if rest != "" {
			// inline content after ---
			sub := &yamlParser{
				lines:   []yamlLine{{strings.Repeat(" ", baseIndent) + rest, l.num}},
				anchors: p.anchors,
			}
			content, err = sub.parseNode(0)
			if err != nil {
				return nil, err
			}
			p.anchors = sub.anchors
			// multiline plain/flow continuation not supported after ---; rare.
		} else {
			content, err = p.parseNode(0)
			if err != nil {
				return nil, err
			}
		}
	} else {
		content, err = p.parseNode(0)
		if err != nil {
			return nil, err
		}
	}
	if content == nil {
		content = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	doc.Content = []*Node{content}
	if doc.Tag == "" {
		doc.Tag = content.Tag
		if content.Kind != ScalarNode {
			doc.Tag = "!!map"
		}
	}
	doc.DocSeparator = doc.DocSeparator || p.docIdx > 0
	p.docIdx++

	// consume optional ... terminator
	if l := p.peek(); l != nil && strings.TrimSpace(l.text) == "..." {
		p.pos++
	}
	return doc, nil
}

const directiveMarker = "\x00D\x00"

// parseNode parses a node whose first significant line is at p.pos (after
// blanks/comments skipped internally), requiring indent >= minIndent.
// Returns nil if nothing at sufficient indent (caller treats as null/empty).
func (p *yamlParser) parseNode(minIndent int) (*Node, error) {
	var head pendingComments
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			head.blank()
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			head.add(l.text)
			p.pos++
			continue
		}
		break
	}
	l := p.peek()
	if l == nil {
		return nil, nil
	}
	ind := indentOf(l.text)
	if ind < minIndent {
		return nil, nil
	}
	content := l.text[ind:]
	if strings.HasPrefix(content, "-") && (len(content) == 1 || content[1] == ' ') {
		return p.parseBlockSeq(ind, &head)
	}
	// mapping? find key
	if k := p.mappingKeyInfo(l); k != nil {
		return p.parseBlockMap(ind, &head)
	}
	// explicit key
	if strings.HasPrefix(content, "? ") || content == "?" {
		return p.parseBlockMap(ind, &head)
	}
	// otherwise scalar-ish (plain/quoted/block/flow/alias/anchor/tag)
	return p.parseScalarOrFlow(minIndent, &head)
}

// mappingKeyInfo reports whether the line starts a block mapping entry.
// It returns the split info (key text, rest after colon).
type mapKey struct {
	keyRaw  string // raw key text (may be quoted/flow)
	rest    string // text after ':' (may be "")
	hasRest bool   // whether there was ': <something>' vs EOL
}

func splitMapKey(line string) *mapKey {
	// scan for ': ' or ':' at end, not inside quotes/brackets
	depth := 0
	i := 0
	n := len(line)
	// handle quoted key
	if i < n && (line[i] == '"' || line[i] == '\'') {
		q := line[i]
		i++
		for i < n {
			if line[i] == q {
				if q == '\'' && i+1 < n && line[i+1] == '\'' {
					i += 2
					continue
				}
				i++
				break
			}
			if q == '"' && line[i] == '\\' {
				i++
			}
			i++
		}
	} else {
		for i < n {
			c := line[i]
			switch c {
			case '[', '{':
				depth++
			case ']', '}':
				depth--
			case '#':
				// ' #' ends plain scalar
				if i > 0 && line[i-1] == ' ' && depth == 0 {
					return nil
				}
			case ':':
				if depth == 0 && (i+1 == n || line[i+1] == ' ') {
					goto found
				}
			case ' ':
			}
			i++
		}
		return nil
	}
found:
	// i at colon (or after quoted key)
	if i < n && (line[0] == '"' || line[0] == '\'') {
		// after closing quote we expect optional spaces then ':'
		j := i
		for j < n && line[j] == ' ' {
			j++
		}
		if j < n && line[j] == ':' && (j+1 == n || line[j+1] == ' ') {
			key := line[:i]
			rest := ""
			hasRest := false
			if j+1 < n {
				rest = line[j+2:]
				hasRest = true
			}
			return &mapKey{keyRaw: key, rest: rest, hasRest: hasRest}
		}
		return nil
	}
	key := line[:i]
	rest := ""
	hasRest := false
	if i+1 < n {
		rest = line[i+2:]
		hasRest = true
	}
	return &mapKey{keyRaw: key, rest: rest, hasRest: hasRest}
}

// parseBlockSeq parses '- item' lines at indent ind.
func (p *yamlParser) parseBlockSeq(ind int, head *pendingComments) (*Node, error) {
	seq := Sequence(0)
	seq.HeadComment = head.String()
	start := p.peek()
	seq.Line = start.num
	seq.Column = ind + 1
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" || strings.HasPrefix(t, "#") {
			// comments/blank inside seq: attach later; for now, peek if seq continues
			next := p.nextSignificant(p.pos)
			if next >= len(p.lines) {
				break
			}
			nl := p.lines[next]
			if indentOf(nl.text) != ind || !strings.HasPrefix(strings.TrimSpace(nl.text), "-") {
				break
			}
			// consume blanks/comments as head comment of next item
			break // handled by outer loop logic below (simplify: stop collection)
		}
		if indentOf(l.text) != ind || !(strings.HasPrefix(l.text[ind:], "-") && (len(l.text[ind:]) == 1 || l.text[ind+1] == ' ')) {
			break
		}
		// an item
		itemLine := l.text[ind+1:]
		itemIndent := ind + 1
		// shift: the item content starts after '-'
		if len(itemLine) > 0 && itemLine[0] == ' ' {
			itemLine = itemLine[1:]
			itemIndent = ind + 2
		}
		// build virtual line for item content and continue parsing from a
		// line-source where this line is replaced by its remainder
		virt := yamlLine{strings.Repeat(" ", itemIndent) + itemLine, l.num}
		p.pos++
		sub := &lineSplicer{main: p, first: &virt}
		node, err := p.parseNodeFrom(sub, itemIndent)
		if err != nil {
			return nil, err
		}
		if node == nil {
			node = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
		}
		seq.Content = append(seq.Content, node)
	}
	return seq, nil
}

// lineSplicer lets a nested parse treat the remainder of an indicator line
// as the first line, then continue with the main line stream.
type lineSplicer struct {
	main  *yamlParser
	first *yamlLine
}

// parseNodeFrom parses a node reading the spliced first line then main lines.
func (p *yamlParser) parseNodeFrom(s *lineSplicer, minIndent int) (*Node, error) {
	fl := s.first
	content := fl.text[indentOf(fl.text):]
	// decide kind from the virtual first line
	if strings.HasPrefix(content, "-") && (len(content) == 1 || content[1] == ' ') {
		// nested sequence starting on same line as '-': e.g. '- - 1'
		return p.parseBlockSeqSpliced(s, indentOf(fl.text))
	}
	if splitMapKey(content) != nil || strings.HasPrefix(content, "? ") || content == "?" {
		return p.parseBlockMapSpliced(s, indentOf(fl.text))
	}
	return p.parseScalarOrFlowSpliced(s, minIndent)
}

func (p *yamlParser) parseBlockMap(ind int, head *pendingComments) (*Node, error) {
	m := Mapping(0)
	m.HeadComment = head.String()
	m.Line = p.peek().num
	m.Column = ind + 1
	err := p.parseMapEntries(m, ind, nil)
	if err != nil {
		return nil, err
	}
	return m, nil
}

func (p *yamlParser) parseBlockMapSpliced(s *lineSplicer, ind int) (*Node, error) {
	m := Mapping(0)
	m.Line = s.first.num
	m.Column = ind + 1
	err := p.parseMapEntries(m, ind, s)
	if err != nil {
		return nil, err
	}
	return m, nil
}

func (p *yamlParser) parseBlockSeqSpliced(s *lineSplicer, ind int) (*Node, error) {
	seq := Sequence(0)
	seq.Line = s.first.num
	seq.Column = ind + 1
	first := s.first
	s.first = nil
	// process the virtual first line as an item
	err := p.seqItemFromLine(seq, *first, ind)
	if err != nil {
		return nil, err
	}
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" || strings.HasPrefix(t, "#") {
			break
		}
		if indentOf(l.text) != ind || !strings.HasPrefix(l.text[ind:], "-") {
			break
		}
		ll := *l
		p.pos++
		if err := p.seqItemFromLine(seq, ll, ind); err != nil {
			return nil, err
		}
	}
	return seq, nil
}

func (p *yamlParser) seqItemFromLine(seq *Node, l yamlLine, ind int) error {
	itemLine := l.text[ind+1:]
	itemIndent := ind + 1
	if len(itemLine) > 0 && itemLine[0] == ' ' {
		itemLine = itemLine[1:]
		itemIndent = ind + 2
	}
	virt := yamlLine{strings.Repeat(" ", itemIndent) + itemLine, l.num}
	sub := &lineSplicer{main: p, first: &virt}
	node, err := p.parseNodeFrom(sub, itemIndent)
	if err != nil {
		return err
	}
	if node == nil {
		node = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	seq.Content = append(seq.Content, node)
	return nil
}

// parseMapEntries parses 'key: value' lines at indent ind into m. If s is
// non-nil, s.first is the first entry line (spliced from a seq indicator).
func (p *yamlParser) parseMapEntries(m *Node, ind int, s *lineSplicer) error {
	cur := s
	for {
		var l yamlLine
		if cur != nil && cur.first != nil {
			l = *cur.first
			cur.first = nil
		} else {
			// skip blanks/comments
			for {
				pl := p.peek()
				if pl == nil {
					return nil
				}
				t := strings.TrimSpace(pl.text)
				if t == "" || strings.HasPrefix(t, "#") {
					p.pos++
					continue
				}
				break
			}
			pl := p.peek()
			if pl == nil || indentOf(pl.text) != ind {
				return nil
			}
			ct := pl.text[ind:]
			if splitMapKey(ct) == nil && !strings.HasPrefix(ct, "? ") && ct != "?" {
				return nil
			}
			if strings.HasPrefix(ct, "-") && (len(ct) == 1 || ct[1] == ' ') {
				return nil
			}
			l = *pl
			p.pos++
		}
		content := l.text[ind:]
		if strings.HasPrefix(content, "? ") || content == "?" {
			// explicit key
			keyText := strings.TrimSpace(strings.TrimPrefix(content, "?"))
			var keyNode *Node
			if keyText == "" {
				// key on following lines
				kn, err := p.parseNode(ind + 1)
				if err != nil {
					return err
				}
				keyNode = kn
				// expect ':'
				for {
					pl := p.peek()
					if pl == nil {
						return nil
					}
					t := strings.TrimSpace(pl.text)
					if t == "" || strings.HasPrefix(t, "#") {
						p.pos++
						continue
					}
					break
				}
				pl := p.peek()
				if pl == nil || indentOf(pl.text) != ind || !strings.HasPrefix(pl.text[ind:], ":") {
					return yamlErr(l.num, "could not find expected ':'")
				}
				l = *pl
				p.pos++
				content = l.text[ind:]
			} else {
				kn, err := p.parseInlineScalar(keyText, l.num)
				if err != nil {
					return err
				}
				keyNode = kn
				// find ':' line
				for {
					pl := p.peek()
					if pl == nil {
						return nil
					}
					t := strings.TrimSpace(pl.text)
					if t == "" || strings.HasPrefix(t, "#") {
						p.pos++
						continue
					}
					break
				}
				pl := p.peek()
				if pl == nil || indentOf(pl.text) != ind || !strings.HasPrefix(pl.text[ind:], ":") {
					return yamlErr(l.num, "could not find expected ':'")
				}
				l = *pl
				p.pos++
				content = l.text[ind:]
			}
			rest := strings.TrimSpace(strings.TrimPrefix(content, ":"))
			var value *Node
			if rest == "" {
				v, err := p.parseNode(ind + 1)
				if err != nil {
					return err
				}
				value = v
			} else {
				virt := yamlLine{strings.Repeat(" ", ind+1) + rest, l.num}
				sub := &lineSplicer{main: p, first: &virt}
				v, err := p.parseNodeFrom(sub, ind+1)
				if err != nil {
					return err
				}
				value = v
			}
			if value == nil {
				value = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
			}
			m.Content = append(m.Content, keyNode, value)
			continue
		}
		mk := splitMapKey(content)
		if mk == nil {
			return nil
		}
		keyNode, err := p.parseInlineScalar(strings.TrimSpace(mk.keyRaw), l.num)
		if err != nil {
			return err
		}
		keyNode.Line = l.num
		keyNode.Column = ind + 1
		var value *Node
		if !mk.hasRest || strings.TrimSpace(stripInlineComment(mk.rest)) == "" {
			// comment on key line with empty value?
			lc := inlineCommentOf(mk.rest)
			// nested block or null
			v, err := p.parseNodeWithComments(ind+1, keyNode)
			if err != nil {
				return err
			}
			value = v
			if value == nil {
				value = &Node{Kind: ScalarNode, Tag: "!!null", Value: "", LineComment: lc}
			} else if lc != "" {
				keyNode.LineComment = lc
			}
		} else {
			rest, lc := splitInlineComment(mk.rest)
			virt := yamlLine{strings.Repeat(" ", ind+1) + rest, l.num}
			sub := &lineSplicer{main: p, first: &virt}
			v, err := p.parseNodeFrom(sub, ind+1)
			if err != nil {
				return err
			}
			value = v
			if value == nil {
				value = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
			}
			if lc != "" && value.LineComment == "" {
				value.LineComment = lc
			}
		}
		value.Line = l.num
		m.Content = append(m.Content, keyNode, value)
	}
}

// parseNodeWithComments handles comment collection for nested blocks:
// comments between 'key:' and its nested block attach as head comment of
// the nested block's first element.
func (p *yamlParser) parseNodeWithComments(minIndent int, keyNode *Node) (*Node, error) {
	return p.parseNode(minIndent)
}

// parseInlineScalar parses a scalar that appears fully within one line
// (keys, simple values). Handles quotes, anchors, tags, aliases, plain.
func (p *yamlParser) parseInlineScalar(text string, lineNum int) (*Node, error) {
	fp := &flowParser{s: text, line: lineNum, anchors: p.anchors}
	n, err := fp.parseNode()
	if err != nil {
		return nil, err
	}
	fp.skipSpace()
	if fp.pos < len(fp.s) {
		rest := strings.TrimSpace(fp.s[fp.pos:])
		if rest != "" && !strings.HasPrefix(rest, "#") {
			return nil, yamlErr(lineNum, "did not find expected comment or line break")
		}
	}
	return n, nil
}

// parseScalarOrFlow handles non-mapping, non-seq content at line level.
func (p *yamlParser) parseScalarOrFlow(minIndent int, head *pendingComments) (*Node, error) {
	l := *p.peek()
	p.pos++
	virt := l
	sub := &lineSplicer{main: p, first: &virt}
	n, err := p.parseScalarOrFlowSpliced(sub, minIndent)
	if err != nil {
		return nil, err
	}
	if n != nil && head != nil && !head.empty() && n.HeadComment == "" {
		n.HeadComment = head.String()
	}
	return n, nil
}

func (p *yamlParser) parseScalarOrFlowSpliced(s *lineSplicer, minIndent int) (*Node, error) {
	l := *s.first
	s.first = nil
	ind := indentOf(l.text)
	content := strings.TrimRight(l.text, " ")
	trimmed := strings.TrimLeft(content, " ")

	// block scalar?
	if idx := blockScalarHeaderIndex(trimmed); idx >= 0 {
		// possible anchor/tag before | or >
		prefix := strings.TrimSpace(trimmed[:idx])
		header := trimmed[idx:]
		node, err := p.parseBlockScalar(header, ind, l.num)
		if err != nil {
			return nil, err
		}
		if prefix != "" {
			if err := p.applyProps(node, prefix, l.num); err != nil {
				return nil, err
			}
		}
		node.Line = l.num
		node.Column = ind + 1
		return node, nil
	}

	// plain scalar possibly multi-line; quoted possibly multi-line; flow
	// possibly multi-line. Collect text starting at this line.
	if trimmed[0] == '"' || trimmed[0] == '\'' || trimmed[0] == '[' || trimmed[0] == '{' {
		// may span multiple lines: gather until balanced
		text, consumed, err := p.gatherFlow(textFromLine(content, ind), l.num)
		if err != nil {
			return nil, err
		}
		_ = consumed
		fp := &flowParser{s: text, line: l.num, anchors: p.anchors}
		n, err := fp.parseNode()
		if err != nil {
			return nil, err
		}
		fp.skipSpace()
		if fp.pos < len(fp.s) {
			rest := strings.TrimSpace(fp.s[fp.pos:])
			if strings.HasPrefix(rest, "#") {
				n.LineComment = strings.TrimSpace(rest[1:])
			} else if rest != "" {
				return nil, yamlErr(l.num, "did not find expected comment or line break")
			}
		}
		n.Line = l.num
		n.Column = ind + 1
		return n, nil
	}

	// anchor/tag/alias/plain scalar on one (or more, for plain) lines
	// gather continuation lines for plain scalars: lines with indent > ind
	text := content[ind:]
	// find inline comment (only for plain scalars)
	mainText, lc := splitInlineComment(text)
	full := strings.TrimRight(mainText, " ")
	// multi-line plain scalar folding
	var extra []string
	save := p.pos
	for {
		nl := p.peek()
		if nl == nil {
			break
		}
		ni := indentOf(nl.text)
		nt := strings.TrimSpace(nl.text)
		if nt == "" {
			// blank line might continue plain scalar if followed by deeper indent
			save2 := p.pos
			p.pos++
			nl2 := p.peek()
			if nl2 != nil && indentOf(nl2.text) > ind && !strings.HasPrefix(strings.TrimSpace(nl2.text), "#") && !startsStruct(nl2.text, ind) {
				extra = append(extra, "")
				save = p.pos
				continue
			}
			p.pos = save2
			break
		}
		if strings.HasPrefix(nt, "#") {
			break
		}
		if ni > ind && !startsStruct(nl.text, ind) {
			extra = append(extra, strings.TrimSpace(splitInlineCommentKeep(nl.text)))
			p.pos++
			save = p.pos
			continue
		}
		break
	}
	p.pos = save
	if len(extra) > 0 {
		full = full + "\n" + strings.Join(extra, "\n")
	}
	fp := &flowParser{s: full, line: l.num, anchors: p.anchors, foldPlain: true}
	n, err := fp.parseNode()
	if err != nil {
		return nil, err
	}
	if lc != "" {
		n.LineComment = lc
	}
	n.Line = l.num
	n.Column = ind + 1
	return n, nil
}

func textFromLine(content string, ind int) string { return content[ind:] }

func startsStruct(line string, ind int) bool {
	i := indentOf(line)
	if i < ind {
		return true
	}
	t := line[i:]
	if strings.HasPrefix(t, "- ") || t == "-" {
		return i <= ind
	}
	if splitMapKey(t) != nil {
		return i <= ind
	}
	return false
}

// gatherFlow collects lines until brackets/quotes balance. Returns combined
// text (with newlines) — assumes p.pos already past first line; consumes more.
func (p *yamlParser) gatherFlow(first string, lineNum int) (string, int, error) {
	text := first
	for !flowComplete(text) {
		nl := p.peek()
		if nl == nil {
			// incomplete flow: let flowParser report the error
			break
		}
		p.pos++
		text += "\n" + nl.text
	}
	return text, 0, nil
}

func flowComplete(s string) bool {
	depth := 0
	var q byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				q = 0
			} else if q == '"' && c == '\\' {
				i++
			}
			continue
		}
		switch c {
		case '"', '\'':
			q = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > 0 && (s[i-1] == ' ' || s[i-1] == '\n') && depth == 0 {
				return true
			}
		}
	}
	return depth <= 0 && q == 0
}

func blockScalarHeaderIndex(trimmed string) int {
	// find | or > that starts the block scalar header, possibly after props
	for i := 0; i < len(trimmed); i++ {
		c := trimmed[i]
		if c == '|' || c == '>' {
			if i == 0 || trimmed[i-1] == ' ' {
				return i
			}
		}
		if c == '#' && i > 0 && trimmed[i-1] == ' ' {
			return -1
		}
	}
	return -1
}

// applyProps parses anchor/tag prefix (e.g. "&a !!str") onto node.
func (p *yamlParser) applyProps(n *Node, prefix string, lineNum int) error {
	fp := &flowParser{s: prefix, line: lineNum, anchors: p.anchors}
	for {
		fp.skipSpace()
		if fp.pos >= len(fp.s) {
			break
		}
		c := fp.s[fp.pos]
		if c == '&' {
			fp.pos++
			name := fp.readAnchorName()
			n.Anchor = name
			fp.anchors[name] = n
		} else if c == '!' {
			tag, err := fp.readTag()
			if err != nil {
				return err
			}
			n.Tag = tag
			n.Style |= TaggedStyle
		} else {
			return yamlErr(lineNum, "did not find expected node content")
		}
	}
	return nil
}

// parseBlockScalar parses | or > header (already on consumed line); content
// lines follow at deeper indent.
func (p *yamlParser) parseBlockScalar(header string, parentIndent int, lineNum int) (*Node, error) {
	style := LiteralStyle
	if header[0] == '>' {
		style = FoldedStyle
	}
	chomp := byte(0)
	explicitIndent := 0
	for i := 1; i < len(header); i++ {
		c := header[i]
		switch {
		case c == '+' || c == '-':
			chomp = c
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		case c == ' ' || c == '\t':
			// rest may be comment
			break
		default:
			return nil, yamlErr(lineNum, "did not find expected comment or line break")
		}
	}
	// collect content lines
	var lines []string
	blockIndent := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if isBlank(l.text) {
			// could belong to block; tentatively include, decide later
			lines = append(lines, "")
			p.pos++
			continue
		}
		ind := indentOf(l.text)
		if blockIndent == -1 {
			if ind <= parentIndent {
				break
			}
			if explicitIndent > 0 {
				blockIndent = parentIndent + explicitIndent
			} else {
				blockIndent = ind
			}
		}
		if ind < blockIndent {
			break
		}
		lines = append(lines, l.text[blockIndent:])
		p.pos++
	}
	// strip trailing blank lines beyond chomp handling
	content := strings.Join(lines, "\n")
	// determine trailing newline count from source lines
	trailing := 0
	for i := len(lines) - 1; i >= 0 && lines[i] == ""; i-- {
		trailing++
	}
	core := strings.TrimRight(content, "\n")
	var val string
	if style == LiteralStyle {
		val = core
	} else {
		val = foldBlockLines(strings.Split(core, "\n"))
	}
	switch chomp {
	case '-':
		// strip
	case '+':
		val += strings.Repeat("\n", trailing+1)
	default:
		val += "\n"
	}
	tag := "!!str"
	return &Node{Kind: ScalarNode, Style: style, Tag: tag, Value: val}, nil
}

func foldBlockLines(lines []string) string {
	var b strings.Builder
	for i, l := range lines {
		if i > 0 {
			prev := lines[i-1]
			if l == "" || prev == "" {
				b.WriteByte('\n')
			} else {
				b.WriteByte(' ')
			}
		}
		b.WriteString(l)
	}
	return b.String()
}

// stripInlineComment removes ' #...' portion.
func stripInlineComment(s string) string {
	r, _ := splitInlineComment(s)
	return r
}

func inlineCommentOf(s string) string {
	_, c := splitInlineComment(s)
	return c
}

// splitInlineComment splits s at ' #' (space then hash) returning content
// (right-trimmed) and comment text (trimmed, without #).
func splitInlineComment(s string) (string, string) {
	inQ := byte(0)
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQ != 0 {
			if c == inQ {
				if inQ == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				inQ = 0
			} else if inQ == '"' && c == '\\' {
				i++
			}
			continue
		}
		switch c {
		case '"', '\'':
			inQ = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') && depth == 0 {
				return strings.TrimRight(s[:i-1], " "), strings.TrimSpace(s[i+1:])
			}
		}
	}
	return strings.TrimRight(s, " "), ""
}

func splitInlineCommentKeep(s string) string {
	r, _ := splitInlineComment(s)
	return r
}

package yq

import (
	"strings"
)

// flowParser parses inline/flow YAML syntax: quoted scalars, flow
// collections, anchors, tags, aliases, plain scalars.
type flowParser struct {
	s         string
	pos       int
	line      int
	anchors   map[string]*Node
	foldPlain bool // multi-line plain scalar: fold newlines to spaces
}

func (f *flowParser) skipSpace() {
	for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t' || f.s[f.pos] == '\n') {
		f.pos++
	}
}

// skipFlowSpace skips spaces/newlines within flow context.
func (f *flowParser) skipFlowSpace() {
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if c == ' ' || c == '\t' || c == '\n' {
			f.pos++
			continue
		}
		if c == '#' {
			// comment to end of line
			for f.pos < len(f.s) && f.s[f.pos] != '\n' {
				f.pos++
			}
			continue
		}
		break
	}
}

func (f *flowParser) readAnchorName() string {
	start := f.pos
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '[' || c == ']' || c == '{' || c == '}' || c == ',' {
			break
		}
		f.pos++
	}
	return f.s[start:f.pos]
}

func (f *flowParser) readTag() (string, error) {
	// at '!'
	f.pos++
	if f.pos < len(f.s) && f.s[f.pos] == '<' {
		end := strings.IndexByte(f.s[f.pos:], '>')
		if end < 0 {
			return "", yamlErr(f.line, "did not find expected '>'")
		}
		tag := "!<" + f.s[f.pos+1:f.pos+end] + ">"
		f.pos += end + 1
		return tag, nil
	}
	start := f.pos
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '[' || c == ']' || c == '{' || c == '}' || c == ',' {
			break
		}
		f.pos++
	}
	word := f.s[start:f.pos]
	if strings.HasPrefix(word, "!") {
		return "!!" + word[1:], nil
	}
	return "!" + word, nil
}

// parseNode parses a complete node in inline context.
func (f *flowParser) parseNode() (*Node, error) {
	f.skipSpace()
	if f.pos >= len(f.s) {
		return &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}, nil
	}
	var anchor, tag string
	var tagged bool
	// properties
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if c == '&' {
			f.pos++
			anchor = f.readAnchorName()
			f.skipSpace()
			continue
		}
		if c == '!' {
			t, err := f.readTag()
			if err != nil {
				return nil, err
			}
			tag = t
			tagged = true
			f.skipSpace()
			continue
		}
		break
	}
	if f.pos >= len(f.s) {
		n := &Node{Kind: ScalarNode, Tag: "!!null", Value: "", Anchor: anchor}
		if anchor != "" {
			f.anchors[anchor] = n
		}
		if tag != "" {
			n.Tag = tag
			if tagged {
				n.Style |= TaggedStyle
			}
		}
		return n, nil
	}
	c := f.s[f.pos]
	var n *Node
	var err error
	switch {
	case c == '\'':
		n, err = f.parseQuoted('\'')
	case c == '"':
		n, err = f.parseQuoted('"')
	case c == '[':
		n, err = f.parseFlowSeq()
	case c == '{':
		n, err = f.parseFlowMap()
	case c == '*':
		f.pos++
		name := f.readAnchorName()
		target := f.anchors[name]
		n = &Node{Kind: AliasNode, Value: name, Alias: target, Tag: "!!alias"}
	default:
		n, err = f.parsePlain()
	}
	if err != nil {
		return nil, err
	}
	if anchor != "" {
		n.Anchor = anchor
		f.anchors[anchor] = n
	}
	if tag != "" {
		n.Tag = tag
		if tagged {
			n.Style |= TaggedStyle
		}
	}
	return n, nil
}

func (f *flowParser) parseQuoted(q byte) (*Node, error) {
	f.pos++ // consume quote
	var b strings.Builder
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if q == '\'' {
			if c == '\'' {
				if f.pos+1 < len(f.s) && f.s[f.pos+1] == '\'' {
					b.WriteByte('\'')
					f.pos += 2
					continue
				}
				f.pos++
				style := SingleQuotedStyle
				return &Node{Kind: ScalarNode, Style: style, Tag: "!!str", Value: b.String()}, nil
			}
			if c == '\n' {
				// fold
				b.WriteByte(' ')
				f.pos++
				for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t') {
					f.pos++
				}
				continue
			}
			b.WriteByte(c)
			f.pos++
			continue
		}
		// double quoted
		if c == '"' {
			f.pos++
			return &Node{Kind: ScalarNode, Style: DoubleQuotedStyle, Tag: "!!str", Value: b.String()}, nil
		}
		if c == '\\' {
			f.pos++
			if f.pos >= len(f.s) {
				break
			}
			e := f.s[f.pos]
			f.pos++
			switch e {
			case '0':
				b.WriteByte(0)
			case 'a':
				b.WriteByte(7)
			case 'b':
				b.WriteByte(8)
			case 't', '\t':
				b.WriteByte(9)
			case 'n':
				b.WriteByte(10)
			case 'v':
				b.WriteByte(11)
			case 'f':
				b.WriteByte(12)
			case 'r':
				b.WriteByte(13)
			case 'e':
				b.WriteByte(27)
			case ' ':
				b.WriteByte(' ')
			case '"':
				b.WriteByte('"')
			case '/':
				b.WriteByte('/')
			case '\\':
				b.WriteByte('\\')
			case 'N':
				b.WriteRune(0x85)
			case '_':
				b.WriteRune(0xa0)
			case 'L':
				b.WriteRune(0x2028)
			case 'P':
				b.WriteRune(0x2029)
			case 'x', 'u', 'U':
				n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[e]
				if f.pos+n > len(f.s) {
					return nil, yamlErr(f.line, "did not find expected hexdecimal number")
				}
				hex := f.s[f.pos : f.pos+n]
				var v rune
				for _, h := range hex {
					v <<= 4
					switch {
					case h >= '0' && h <= '9':
						v |= h - '0'
					case h >= 'a' && h <= 'f':
						v |= h - 'a' + 10
					case h >= 'A' && h <= 'F':
						v |= h - 'A' + 10
					default:
						return nil, yamlErr(f.line, "did not find expected hexdecimal number")
					}
				}
				b.WriteRune(v)
				f.pos += n
			case '\n':
				// line continuation
				for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t') {
					f.pos++
				}
			default:
				return nil, yamlErr(f.line, "found unknown escape character")
			}
			continue
		}
		if c == '\n' {
			b.WriteByte(' ')
			f.pos++
			for f.pos < len(f.s) && (f.s[f.pos] == ' ' || f.s[f.pos] == '\t') {
				f.pos++
			}
			continue
		}
		b.WriteByte(c)
		f.pos++
	}
	return nil, yamlErr(f.line, "found unexpected end of stream")
}

// parsePlain parses a plain scalar (block or flow context).
func (f *flowParser) parsePlain() (*Node, error) {
	start := f.pos
	depth := 0
	for f.pos < len(f.s) {
		c := f.s[f.pos]
		if c == '\n' {
			if f.foldPlain {
				f.pos++
				continue
			}
			break
		}
		if depth == 0 {
			if c == ',' || c == ']' || c == '}' {
				break
			}
			if c == ':' && f.pos+1 < len(f.s) && (f.s[f.pos+1] == ' ' || f.s[f.pos+1] == '\n') {
				break
			}
			if c == '#' && f.pos > start && f.s[f.pos-1] == ' ' {
				break
			}
		}
		switch c {
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		}
		f.pos++
	}
	raw := f.s[start:f.pos]
	// trim trailing spaces (before comment/comma)
	raw = strings.TrimRight(raw, " \t")
	if f.foldPlain {
		// fold single newlines to space; blank lines to newline
		raw = foldPlainScalar(raw)
	}
	raw = strings.TrimSpace(raw)
	tag, value := ResolveScalar(raw)
	if raw == "<<" {
		tag = "!!merge"
	}
	n := &Node{Kind: ScalarNode, Tag: tag, Value: value}
	if raw == "" {
		n.Tag = "!!null"
		n.Value = ""
	}
	return n, nil
}

func foldPlainScalar(s string) string {
	var b strings.Builder
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lt := strings.Trim(l, " \t")
		if i == 0 {
			b.WriteString(lt)
			continue
		}
		prev := strings.Trim(lines[i-1], " \t")
		if prev == "" || lt == "" {
			b.WriteByte('\n')
		} else {
			b.WriteByte(' ')
		}
		b.WriteString(lt)
	}
	return b.String()
}

func (f *flowParser) parseFlowSeq() (*Node, error) {
	f.pos++ // [
	seq := Sequence(FlowStyle)
	seq.Line = f.line
	f.skipFlowSpace()
	if f.pos < len(f.s) && f.s[f.pos] == ']' {
		f.pos++
		return seq, nil
	}
	for {
		f.skipFlowSpace()
		n, err := f.parseFlowEntry()
		if err != nil {
			return nil, err
		}
		seq.Content = append(seq.Content, n)
		f.skipFlowSpace()
		if f.pos >= len(f.s) {
			return nil, yamlErr(f.line, "did not find expected ',' or ']'")
		}
		c := f.s[f.pos]
		if c == ',' {
			f.pos++
			continue
		}
		if c == ']' {
			f.pos++
			return seq, nil
		}
		return nil, yamlErr(f.line, "did not find expected ',' or ']'")
	}
}

// parseFlowEntry parses one flow sequence entry (which may itself be
// 'key: value' forming a single-pair map).
func (f *flowParser) parseFlowEntry() (*Node, error) {
	save := f.pos
	n, err := f.parseNode()
	if err != nil {
		return nil, err
	}
	f.skipFlowSpace()
	if f.pos < len(f.s) && f.s[f.pos] == ':' {
		// key: value single pair map
		f.pos++
		f.skipFlowSpace()
		var v *Node
		if f.pos < len(f.s) && (f.s[f.pos] == ',' || f.s[f.pos] == ']' || f.s[f.pos] == '}') {
			v = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
		} else {
			v, err = f.parseFlowEntry()
			if err != nil {
				return nil, err
			}
		}
		m := Mapping(FlowStyle)
		m.Content = []*Node{n, v}
		return m, nil
	}
	_ = save
	return n, nil
}

func (f *flowParser) parseFlowMap() (*Node, error) {
	f.pos++ // {
	m := Mapping(FlowStyle)
	m.Line = f.line
	f.skipFlowSpace()
	if f.pos < len(f.s) && f.s[f.pos] == '}' {
		f.pos++
		return m, nil
	}
	for {
		f.skipFlowSpace()
		// explicit key '?'
		if f.pos < len(f.s) && f.s[f.pos] == '?' {
			f.pos++
			f.skipFlowSpace()
		}
		k, err := f.parseFlowEntry()
		if err != nil {
			return nil, err
		}
		// k may already be a single-pair map (from 'a: b')
		if k.Kind == MappingNode {
			for i := 0; i < len(k.Content); i += 2 {
				m.Content = append(m.Content, k.Content[i], k.Content[i+1])
			}
		} else {
			// key with no value
			m.Content = append(m.Content, k, &Node{Kind: ScalarNode, Tag: "!!null", Value: ""})
		}
		f.skipFlowSpace()
		if f.pos >= len(f.s) {
			return nil, yamlErr(f.line, "did not find expected ',' or '}'")
		}
		c := f.s[f.pos]
		if c == ',' {
			f.pos++
			continue
		}
		if c == '}' {
			f.pos++
			return m, nil
		}
		return nil, yamlErr(f.line, "did not find expected ',' or '}'")
	}
}

package yq

import (
	"regexp"
	"strconv"
	"strings"
)

// ResolveScalar implements the YAML 1.2 core schema resolution as done by
// gopkg.in/yaml.v3 (including its quirks: 0x/0o/0b ints, legacy octal,
// underscores, big-int-to-float, timestamps).
func ResolveScalar(value string) (tag string, out string) {
	switch value {
	case "", "~", "null", "Null", "NULL":
		return "!!null", value
	case "true", "True", "TRUE", "false", "False", "FALSE":
		return "!!bool", value
	case "<<":
		return "!!merge", value
	case ".nan", ".NaN", ".NAN":
		return "!!float", value
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF":
		return "!!float", value
	}

	// timestamps (yaml.v3 formats)
	if isTimestamp(value) {
		return "!!timestamp", value
	}

	// integers
	if isIntLike(value) {
		return "!!int", value
	}
	// floats
	if isFloatLike(value) {
		return "!!float", value
	}
	return "!!str", value
}

var tsRegexes = []*regexp.Regexp{
	regexp.MustCompile(`^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$`),
	regexp.MustCompile(`^[0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?([Tt]|[ \t]+)[0-9][0-9]?:[0-9][0-9]:[0-9][0-9](\.[0-9]*)?(([ \t]*)Z|[-+][0-9][0-9]?(:[0-9][0-9])?)?$`),
}

func isTimestamp(s string) bool {
	for _, r := range tsRegexes {
		if r.MatchString(s) {
			return true
		}
	}
	return false
}

func isIntLike(s string) bool {
	t := strings.ReplaceAll(s, "_", "")
	if t == "" {
		return false
	}
	body := t
	if body[0] == '+' || body[0] == '-' {
		body = body[1:]
		if body == "" {
			return false
		}
	}
	if strings.HasPrefix(body, "0b") {
		return allDigits(body[2:], '0', '1')
	}
	if strings.HasPrefix(body, "0o") {
		return allDigits(body[2:], '0', '7')
	}
	if strings.HasPrefix(body, "0x") {
		return isHex(body[2:])
	}
	if len(body) > 1 && body[0] == '0' {
		// legacy octal: 0[0-7]+  (yaml.v3 resolves as int)
		return allDigits(body[1:], '0', '7')
	}
	for _, c := range body {
		if c < '0' || c > '9' {
			return false
		}
	}
	// overflow check: yaml.v3 falls back to float for big decimals
	if _, err := strconv.ParseInt(t, 0, 64); err != nil {
		if _, ferr := strconv.ParseFloat(t, 64); ferr == nil {
			return false // -> will be matched as float? no: tag float
		}
		return false
	}
	return true
}

var floatRe = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9][0-9_]*(\.[0-9_]*)?)([eE][-+]?[0-9]+)?$`)

func isFloatLike(s string) bool {
	if !floatRe.MatchString(s) {
		return false
	}
	// must contain '.', 'e' or be big-int overflow; plain digits already int
	t := strings.ReplaceAll(s, "_", "")
	if !strings.ContainsAny(t, ".eE") {
		// big int overflow case
		if _, err := strconv.ParseInt(t, 0, 64); err != nil {
			if _, ferr := strconv.ParseFloat(t, 64); ferr == nil {
				return true
			}
		}
		return false
	}
	// reject things like "1.2.3"
	if strings.Count(t, ".") > 1 {
		return false
	}
	// reject leading zeros like 01.5? yaml allows... keep simple
	_, err := strconv.ParseFloat(t, 64)
	if err != nil {
		// e.g. "5." or ".5" or "1.e2" ParseFloat accepts "5." and ".5"
		return false
	}
	return true
}

func allDigits(s string, lo, hi byte) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < lo || s[i] > hi {
			return false
		}
	}
	return true
}

func isHex(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

// ParseIntValue parses a !!int node's value to int64, yaml.v3 style.
func ParseIntValue(v string) (int64, error) {
	t := strings.ReplaceAll(v, "_", "")
	neg := false
	body := t
	if strings.HasPrefix(body, "+") {
		body = body[1:]
	} else if strings.HasPrefix(body, "-") {
		neg = true
		body = body[1:]
	}
	var n int64
	var err error
	switch {
	case strings.HasPrefix(body, "0b"):
		n, err = strconv.ParseInt(body[2:], 2, 64)
	case strings.HasPrefix(body, "0o"):
		n, err = strconv.ParseInt(body[2:], 8, 64)
	case strings.HasPrefix(body, "0x"):
		n, err = strconv.ParseInt(body[2:], 16, 64)
	case len(body) > 1 && strings.HasPrefix(body, "0") && allDigits(body[1:], '0', '7'):
		n, err = strconv.ParseInt(body, 8, 64)
	default:
		n, err = strconv.ParseInt(body, 10, 64)
	}
	if neg {
		n = -n
	}
	return n, err
}

// ParseFloatValue parses a !!float node's value.
func ParseFloatValue(v string) (float64, error) {
	t := strings.ReplaceAll(v, "_", "")
	switch strings.ToLower(t) {
	case ".inf", "+.inf":
		return strconv.ParseFloat("+Inf", 64)
	case "-.inf":
		return strconv.ParseFloat("-Inf", 64)
	case ".nan":
		return strconv.ParseFloat("NaN", 64)
	}
	return strconv.ParseFloat(t, 64)
}

package yq

import (
	"fmt"
	"strings"
)

// DumpNode renders a debug view of a node tree.
func DumpNode(n *Node) string {
	var b strings.Builder
	dumpNode(&b, n, 0)
	return b.String()
}

func dumpNode(b *strings.Builder, n *Node, depth int) {
	if n == nil {
		fmt.Fprintf(b, "%s<nil>\n", strings.Repeat("  ", depth))
		return
	}
	fmt.Fprintf(b, "%sKind=%d Style=%d Tag=%q Value=%q Anchor=%q HC=%q LC=%q FC=%q L=%d C=%d\n",
		strings.Repeat("  ", depth), int(n.Kind), int(n.Style), n.Tag, n.Value, n.Anchor,
		n.HeadComment, n.LineComment, n.FootComment, n.Line, n.Column)
	for _, c := range n.Content {
		dumpNode(b, c, depth+1)
	}
}

