package yq

import (
	"fmt"
	"strings"
)

// A from-scratch YAML (1.2 core-schema) parser producing *Node trees with
// comment/anchor/tag/style fidelity approximating gopkg.in/yaml.v3.

type yamlLine struct {
	text string // raw line without trailing \n (and without trailing \r)
	num  int    // 1-based
}

// YamlParseError mimics yaml.v3 error strings where feasible.
type YamlParseError struct{ Msg string }

func (e *YamlParseError) Error() string { return "yaml: " + e.Msg }

func yamlErr(line int, format string, args ...interface{}) error {
	return &YamlParseError{Msg: fmt.Sprintf("line %d: %s", line, fmt.Sprintf(format, args...))}
}

type yamlParser struct {
	lines   []yamlLine
	pos     int
	anchors map[string]*Node
	docIdx  int
}

// comments tracks pending comment lines while scanning collections.
type comments struct {
	lines []string // comment text lines; "" = blank separator inside block
}

func (c *comments) add(raw string) {
	t := strings.TrimLeft(raw, " ")
	if strings.HasPrefix(t, "#") {
		t = t[1:]
		if strings.HasPrefix(t, " ") {
			t = t[1:]
		}
		c.lines = append(c.lines, t)
	}
}

// blank records a blank line: only meaningful inside/after a comment block.
func (c *comments) blank() {
	if len(c.lines) > 0 {
		c.lines = append(c.lines, "")
	}
}

func (c *comments) String() string {
	s := strings.Join(c.lines, "\n")
	return strings.TrimRight(s, "\n")
}
func (c *comments) empty() bool { return len(c.lines) == 0 }
func (c *comments) reset()      { c.lines = nil }

// ParseYAML parses a whole stream into document nodes.
func ParseYAML(data []byte) ([]*Node, error) {
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	raw := strings.Split(s, "\n")
	if len(raw) > 0 && raw[len(raw)-1] == "" {
		raw = raw[:len(raw)-1]
	}
	lines := make([]yamlLine, len(raw))
	for i, l := range raw {
		lines[i] = yamlLine{l, i + 1}
	}
	p := &yamlParser{lines: lines, anchors: map[string]*Node{}}
	var docs []*Node
	for {
		doc, err := p.parseDocument()
		if err != nil {
			return nil, err
		}
		if doc == nil {
			break
		}
		docs = append(docs, doc)
	}
	if len(docs) == 0 {
		d := &Node{Kind: DocumentNode, Tag: "!!null", Content: []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}}
		docs = append(docs, d)
	}
	for i, d := range docs {
		d.DocIndex = i
	}
	return docs, nil
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isBlank(s string) bool { return strings.TrimSpace(s) == "" }

func (p *yamlParser) peek() *yamlLine {
	if p.pos >= len(p.lines) {
		return nil
	}
	return &p.lines[p.pos]
}

const directiveMarker = "\x00D\x00"

// parseDocument parses one document; returns nil at EOF.
func (p *yamlParser) parseDocument() (*Node, error) {
	var head comments
	sawAny := false
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			head.blank()
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			head.add(l.text)
			p.pos++
			sawAny = true
			continue
		}
		if strings.HasPrefix(t, "%") {
			head.lines = append(head.lines, directiveMarker+t)
			p.pos++
			sawAny = true
			continue
		}
		break
	}

	l := p.peek()
	if l == nil {
		if !sawAny {
			return nil, nil
		}
		d := &Node{Kind: DocumentNode, Tag: "!!null", HeadComment: head.String(),
			Content: []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}}
		d.DocSeparator = p.docIdx > 0
		p.docIdx++
		return d, nil
	}

	doc := &Node{Kind: DocumentNode}
	doc.HeadComment = head.String()
	doc.Line = l.num

	trimmed := strings.TrimSpace(l.text)
	if trimmed == "..." {
		p.pos++
		doc.Tag = "!!null"
		doc.Content = []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}
		doc.DocSeparator = p.docIdx > 0
		p.docIdx++
		return doc, nil
	}

	var content *Node
	var trail *comments
	var err error
	if strings.HasPrefix(trimmed, "---") {
		rest := strings.TrimPrefix(trimmed, "---")
		if rest != "" && rest[0] != ' ' && rest[0] != '\t' && rest[0] != '#' {
			return nil, yamlErr(l.num, "did not find expected comment or line break")
		}
		doc.DocSeparator = true
		baseIndent := indentOf(l.text)
		restPart := rest
		if idx := strings.Index(restPart, " #"); idx >= 0 {
			restPart = restPart[:idx]
		}
		restPart = strings.TrimSpace(restPart)
		p.pos++
		if restPart != "" {
			sub := &yamlParser{
				lines:   []yamlLine{{strings.Repeat(" ", baseIndent) + restPart, l.num}},
				anchors: p.anchors,
			}
			content, err = sub.parseNode(0, -1)
			if err != nil {
				return nil, err
			}
			p.anchors = sub.anchors
		} else {
			content, trail, err = p.parseNode(0, -1)
			if err != nil {
				return nil, err
			}
		}
	} else {
		content, trail, err = p.parseNode(0, -1)
		if err != nil {
			return nil, err
		}
	}
	if content == nil {
		content = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	doc.Content = []*Node{content}
	if doc.Tag == "" {
		doc.Tag = content.Tag
		if content.Kind != ScalarNode {
			doc.Tag = "!!map"
		}
	}
	// copy doc head comment onto root collection like yaml.v3 does
	if content.Kind != ScalarNode && content.HeadComment == "" && doc.HeadComment != "" {
		content.HeadComment = doc.HeadComment
	}
	// trailing unconsumed comments: foot comment of deepest last key/item
	if trail != nil && !trail.empty() {
		attachTrailingFootComment(content, trail.String())
	}
	doc.DocSeparator = doc.DocSeparator || p.docIdx > 0
	p.docIdx++

	if l := p.peek(); l != nil && strings.TrimSpace(l.text) == "..." {
		p.pos++
	}
	return doc, nil
}

// attachTrailingFootComment walks to the deepest last entry and sets FC.
func attachTrailingFootComment(n *Node, fc string) {
	for {
		switch n.Kind {
		case DocumentNode:
			n = n.Content[0]
		case MappingNode:
			if len(n.Content) == 0 {
				return
			}
			key := n.Content[len(n.Content)-2]
			val := n.Content[len(n.Content)-1]
			if val.Kind == MappingNode || val.Kind == SequenceNode || val.Kind == DocumentNode {
				n = val
				continue
			}
			key.FootComment = fc
			return
		case SequenceNode:
			if len(n.Content) == 0 {
				return
			}
			last := n.Content[len(n.Content)-1]
			if last.Kind == MappingNode || last.Kind == SequenceNode {
				n = last
				continue
			}
			last.FootComment = fc
			return
		default:
			n.FootComment = fc
			return
		}
	}
}

// parseNode parses a node at the current position. blockParent is the
// indentation of the enclosing block structure (for block scalar content).
// Returns the node (possibly nil), trailing unconsumed comments, error.
func (p *yamlParser) parseNode(minIndent int, blockParent int) (*Node, *comments, error) {
	var head comments
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			head.blank()
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			head.add(l.text)
			p.pos++
			continue
		}
		break
	}
	l := p.peek()
	if l == nil {
		return nil, &head, nil
	}
	ind := indentOf(l.text)
	if ind < minIndent {
		return nil, &head, nil
	}
	content := l.text[ind:]
	if strings.HasPrefix(content, "-") && (len(content) == 1 || content[1] == ' ') {
		n, tr, err := p.parseBlockSeq(ind)
		if n != nil && !head.empty() {
			n.HeadComment = head.String()
		}
		return n, tr, err
	}
	if splitMapKey(content) != nil || strings.HasPrefix(content, "? ") || content == "?" {
		n, tr, err := p.parseBlockMap(ind)
		if n != nil && !head.empty() {
			n.HeadComment = head.String()
		}
		return n, tr, err
	}
	n, err := p.parseScalarOrFlow(ind, blockParent)
	if n != nil && !head.empty() && n.HeadComment == "" {
		n.HeadComment = head.String()
	}
	return n, nil, err
}

// mapKey holds split info for 'key: value' lines.
type mapKey struct {
	keyRaw  string
	rest    string
	hasRest bool // ': ' followed by content
}

func splitMapKey(line string) *mapKey {
	depth := 0
	i := 0
	n := len(line)
	if n > 0 && (line[0] == '"' || line[0] == '\'') {
		q := line[0]
		i = 1
		for i < n {
			if line[i] == q {
				if q == '\'' && i+1 < n && line[i+1] == '\'' {
					i += 2
					continue
				}
				i++
				break
			}
			if q == '"' && line[i] == '\\' {
				i++
			}
			i++
		}
		// after quoted key expect spaces then ':'
		j := i
		for j < n && line[j] == ' ' {
			j++
		}
		if j < n && line[j] == ':' && (j+1 == n || line[j+1] == ' ') {
			mk := &mapKey{keyRaw: line[:i]}
			if j+1 < n {
				mk.rest = line[j+2:]
				mk.hasRest = true
			}
			return mk
		}
		return nil
	}
	for i < n {
		c := line[i]
		switch c {
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > 0 && line[i-1] == ' ' && depth == 0 {
				return nil
			}
		case ':':
			if depth == 0 && (i+1 == n || line[i+1] == ' ') {
				mk := &mapKey{keyRaw: line[:i]}
				if i+1 < n {
					mk.rest = line[i+2:]
					mk.hasRest = true
				}
				return mk
			}
		}
		i++
	}
	return nil
}

// parseBlockSeq parses '- item' lines at indent ind.
func (p *yamlParser) parseBlockSeq(ind int) (*Node, *comments, error) {
	seq := Sequence(0)
	seq.Line = p.peek().num
	seq.Column = ind + 1
	var pend comments
	var prevItem *Node
	flushFC := func() {
		if !pend.empty() && prevItem != nil {
			attachItemFC(prevItem, pend.String())
		}
		pend.reset()
	}
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			if !pend.empty() {
				// blank after comments: flush as FC of previous item
				flushFC()
			}
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			pend.add(l.text)
			p.pos++
			continue
		}
		if indentOf(l.text) != ind {
			break
		}
		ct := l.text[ind:]
		if !(strings.HasPrefix(ct, "-") && (len(ct) == 1 || ct[1] == ' ')) {
			break
		}
		p.pos++
		node, trail, err := p.parseSeqItem(l, ind)
		if err != nil {
			return nil, nil, err
		}
		if node == nil {
			node = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
		}
		if !pend.empty() {
			if node.HeadComment == "" {
				node.HeadComment = pend.String()
			}
			pend.reset()
		}
		if trail != nil && !trail.empty() {
			pend = *trail
		}
		seq.Content = append(seq.Content, node)
		prevItem = node
	}
	return seq, &pend, nil
}

// attachItemFC sets FC on an item (descending into nested collections).
func attachItemFC(n *Node, fc string) {
	attachTrailingFootComment(n, fc)
}

func (p *yamlParser) parseSeqItem(l *yamlLine, ind int) (*Node, *comments, error) {
	itemLine := l.text[ind+1:]
	itemIndent := ind + 1
	if len(itemLine) > 0 && itemLine[0] == ' ' {
		itemLine = itemLine[1:]
		itemIndent = ind + 2
	}
	virt := yamlLine{strings.Repeat(" ", itemIndent) + itemLine, l.num}
	sub := &splicedParser{main: p, first: &virt}
	return sub.parseSplicedNode(itemIndent, ind)
}

// splicedParser parses a node whose first line is the remainder of an
// indicator line ('- ' or 'key: ').
type splicedParser struct {
	main  *yamlParser
	first *yamlLine
}

func (s *splicedParser) parseSplicedNode(minIndent int, blockParent int) (*Node, *comments, error) {
	p := s.main
	fl := *s.first
	s.first = nil
	ind := indentOf(fl.text)
	content := fl.text[ind:]

	if strings.HasPrefix(content, "-") && (len(content) == 1 || content[1] == ' ') {
		// nested sequence, e.g. '- - 1'
		return p.parseBlockSeqFirst(fl, ind)
	}
	if splitMapKey(content) != nil || strings.HasPrefix(content, "? ") || content == "?" {
		return p.parseBlockMapFirst(fl, ind)
	}
	n, err := p.parseScalarOrFlowLine(fl, blockParent)
	return n, nil, err
}

// parseBlockSeqFirst parses a block sequence whose first line is given.
func (p *yamlParser) parseBlockSeqFirst(fl yamlLine, ind int) (*Node, *comments, error) {
	seq := Sequence(0)
	seq.Line = fl.num
	seq.Column = ind + 1
	node, trail, err := p.parseSeqItem(&fl, ind)
	if err != nil {
		return nil, nil, err
	}
	if node == nil {
		node = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
	}
	seq.Content = append(seq.Content, node)
	var pend comments
	if trail != nil {
		pend = *trail
	}
	prevItem := node
	flushFC := func() {
		if !pend.empty() && prevItem != nil {
			attachItemFC(prevItem, pend.String())
		}
		pend.reset()
	}
	for {
		l := p.peek()
		if l == nil {
			break
		}
		t := strings.TrimSpace(l.text)
		if t == "" {
			if !pend.empty() {
				flushFC()
			}
			p.pos++
			continue
		}
		if strings.HasPrefix(t, "#") {
			pend.add(l.text)
			p.pos++
			continue
		}
		if indentOf(l.text) != ind {
			break
		}
		ct := l.text[ind:]
		if !(strings.HasPrefix(ct, "-") && (len(ct) == 1 || ct[1] == ' ')) {
			break
		}
		p.pos++
		node, trail, err := p.parseSeqItem(l, ind)
		if err != nil {
			return nil, nil, err
		}
		if node == nil {
			node = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
		}
		if !pend.empty() {
			if node.HeadComment == "" {
				node.HeadComment = pend.String()
			}
			pend.reset()
		}
		if trail != nil && !trail.empty() {
			pend = *trail
		}
		seq.Content = append(seq.Content, node)
		prevItem = node
	}
	return seq, &pend, nil
}

// parseBlockMap parses 'key: value' lines at indent ind.
func (p *yamlParser) parseBlockMap(ind int) (*Node, *comments, error) {
	m := Mapping(0)
	m.Line = p.peek().num
	m.Column = ind + 1
	trail, err := p.parseMapEntries(m, ind, nil)
	if err != nil {
		return nil, nil, err
	}
	return m, trail, nil
}

// parseBlockMapFirst parses a block map whose first entry line is given
// (spliced from '- ' or ': ' remainder).
func (p *yamlParser) parseBlockMapFirst(fl yamlLine, ind int) (*Node, *comments, error) {
	m := Mapping(0)
	m.Line = fl.num
	m.Column = ind + 1
	trail, err := p.parseMapEntries(m, ind, &fl)
	if err != nil {
		return nil, nil, err
	}
	return m, trail, nil
}

// parseMapEntries parses entries at indent ind into m. first, if non-nil,
// is a spliced first entry line. Returns trailing unconsumed comments.
func (p *yamlParser) parseMapEntries(m *Node, ind int, first *yamlLine) (*comments, error) {
	var pend comments
	var prevKey *Node
	flushFC := func() {
		if !pend.empty() && prevKey != nil {
			attachTrailingFootComment(prevKey, pend.String())
			pend.reset()
		}
	}
	for {
		var l yamlLine
		if first != nil {
			l = *first
			first = nil
		} else {
			for {
				pl := p.peek()
				if pl == nil {
					flushFC()
					return &pend, nil
				}
				t := strings.TrimSpace(pl.text)
				if t == "" {
					if !pend.empty() {
						flushFC()
					}
					p.pos++
					continue
				}
				if strings.HasPrefix(t, "#") {
					pend.add(pl.text)
					p.pos++
					continue
				}
				break
			}
			pl := p.peek()
			if indentOf(pl.text) != ind {
				return &pend, nil
			}
			ct := pl.text[ind:]
			if strings.HasPrefix(ct, "-") && (len(ct) == 1 || ct[1] == ' ') {
				return &pend, nil
			}
			if splitMapKey(ct) == nil && !strings.HasPrefix(ct, "? ") && ct != "?" {
				return &pend, nil
			}
			l = *pl
			p.pos++
		}
		content := l.text[ind:]
		var keyNode *Node
		var err error
		var value *Node
		var trail *comments

		if strings.HasPrefix(content, "? ") || content == "?" {
			keyText := strings.TrimSpace(strings.TrimPrefix(content, "?"))
			if keyText != "" {
				keyNode, err = p.parseInlineScalar(keyText, l.num)
				if err != nil {
					return nil, err
				}
			} else {
				kn, _, err := p.parseNode(ind+1, ind)
				if err != nil {
					return nil, err
				}
				keyNode = kn
			}
			// find ':' line
			var cline *yamlLine
			for {
				pl := p.peek()
				if pl == nil {
					break
				}
				t := strings.TrimSpace(pl.text)
				if t == "" || strings.HasPrefix(t, "#") {
					p.pos++
					continue
				}
				break
			}
			cline = p.peek()
			if cline == nil || indentOf(cline.text) != ind || !strings.HasPrefix(cline.text[ind:], ":") {
				return nil, yamlErr(l.num, "could not find expected ':'")
			}
			l = *cline
			p.pos++
			content = l.text[ind:]
			rest := strings.TrimSpace(strings.TrimPrefix(content, ":"))
			if rest == "" {
				value, trail, err = p.parseNode(ind+1, ind)
				if err != nil {
					return nil, err
				}
			} else {
				virt := yamlLine{strings.Repeat(" ", ind+1) + rest, l.num}
				sub := &splicedParser{main: p, first: &virt}
				value, trail, err = sub.parseSplicedNode(ind+1, ind)
				if err != nil {
					return nil, err
				}
			}
			if keyNode == nil {
				keyNode = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
			}
			if value == nil {
				value = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
			}
		} else {
			mk := splitMapKey(content)
			if mk == nil {
				return &pend, nil
			}
			keyNode, err = p.parseInlineScalar(strings.TrimSpace(mk.keyRaw), l.num)
			if err != nil {
				return nil, err
			}
			keyNode.Line = l.num
			keyNode.Column = ind + 1
			rest, lc := splitInlineComment(mk.rest)
			if !mk.hasRest || strings.TrimSpace(rest) == "" {
				value, trail, err = p.parseNode(ind+1, ind)
				if err != nil {
					return nil, err
				}
				if value == nil {
					value = &Node{Kind: ScalarNode, Tag: "!!null", Value: "", LineComment: lc}
				} else if lc != "" {
					keyNode.LineComment = lc
				}
			} else {
				virt := yamlLine{strings.Repeat(" ", ind+1) + rest, l.num}
				sub := &splicedParser{main: p, first: &virt}
				value, trail, err = sub.parseSplicedNode(ind+1, ind)
				if err != nil {
					return nil, err
				}
				if value == nil {
					value = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
				}
				if lc != "" && value.LineComment == "" {
					value.LineComment = lc
				}
			}
		}
		if value == nil {
			value = &Node{Kind: ScalarNode, Tag: "!!null", Value: ""}
		}
		if value.Line == 0 {
			value.Line = l.num
		}
		if !pend.empty() {
			if keyNode.HeadComment == "" {
				keyNode.HeadComment = pend.String()
			}
			pend.reset()
		}
		if trail != nil && !trail.empty() {
			pend = *trail
		}
		m.Content = append(m.Content, keyNode, value)
		prevKey = keyNode
	}
}

// parseInlineScalar parses a scalar appearing fully within one line.
func (p *yamlParser) parseInlineScalar(text string, lineNum int) (*Node, error) {
	fp := &flowParser{s: text, line: lineNum, anchors: p.anchors}
	n, err := fp.parseNode()
	if err != nil {
		return nil, err
	}
	fp.skipSpace()
	if fp.pos < len(fp.s) {
		rest := strings.TrimSpace(fp.s[fp.pos:])
		if rest != "" && !strings.HasPrefix(rest, "#") {
			return nil, yamlErr(lineNum, "did not find expected comment or line break")
		}
	}
	return n, nil
}

// parseScalarOrFlow parses non-collection content; current line is the start.
func (p *yamlParser) parseScalarOrFlow(minIndent int, blockParent int) (*Node, error) {
	l := *p.peek()
	p.pos++
	return p.parseScalarOrFlowLine(l, blockParent)
}

func (p *yamlParser) parseScalarOrFlowLine(l yamlLine, blockParent int) (*Node, error) {
	ind := indentOf(l.text)
	content := strings.TrimRight(l.text, " ")
	trimmed := strings.TrimLeft(content, " ")

	// block scalar (| or >), possibly after anchor/tag props
	if idx := blockScalarHeaderIndex(trimmed); idx >= 0 {
		prefix := strings.TrimSpace(trimmed[:idx])
		header := trimmed[idx:]
		node, err := p.parseBlockScalar(header, blockParent, l.num)
		if err != nil {
			return nil, err
		}
		if prefix != "" {
			if err := p.applyProps(node, prefix, l.num); err != nil {
				return nil, err
			}
		}
		node.Line = l.num
		node.Column = ind + 1
		return node, nil
	}

	// quoted or flow collections may span lines
	if trimmed[0] == '"' || trimmed[0] == '\'' || trimmed[0] == '[' || trimmed[0] == '{' {
		text := p.gatherFlow(content[ind:], l.num)
		fp := &flowParser{s: text, line: l.num, anchors: p.anchors}
		n, err := fp.parseNode()
		if err != nil {
			return nil, err
		}
		fp.skipSpace()
		if fp.pos < len(fp.s) {
			rest := strings.TrimSpace(fp.s[fp.pos:])
			if strings.HasPrefix(rest, "#") {
				n.LineComment = strings.TrimSpace(rest[1:])
			} else if rest != "" {
				return nil, yamlErr(l.num, "did not find expected comment or line break")
			}
		}
		n.Line = l.num
		n.Column = ind + 1
		return n, nil
	}

	// anchor/tag/alias/plain scalar; plain may continue on deeper lines
	text := content[ind:]
	mainText, lc := splitInlineComment(text)
	full := mainText
	var extra []string
	for {
		nl := p.peek()
		if nl == nil {
			break
		}
		ni := indentOf(nl.text)
		nt := strings.TrimSpace(nl.text)
		if nt == "" {
			// blank: continues plain scalar only if next is deeper continuation
			save := p.pos
			p.pos++
			nl2 := p.peek()
			if nl2 != nil && indentOf(nl2.text) > ind {
				t2 := strings.TrimSpace(nl2.text)
				if t2 != "" && !strings.HasPrefix(t2, "#") && !startsStruct(nl2.text, ind) {
					extra = append(extra, "")
					continue
				}
			}
			p.pos = save
			break
		}
		if strings.HasPrefix(nt, "#") {
			break
		}
		if ni > ind && !startsStruct(nl.text, ind) {
			extra = append(extra, strings.TrimSpace(stripInlineComment(nl.text)))
			p.pos++
			continue
		}
		break
	}
	if len(extra) > 0 {
		full = full + "\n" + strings.Join(extra, "\n")
	}
	fp := &flowParser{s: full, line: l.num, anchors: p.anchors, foldPlain: true}
	n, err := fp.parseNode()
	if err != nil {
		return nil, err
	}
	if lc != "" {
		n.LineComment = lc
	}
	n.Line = l.num
	n.Column = ind + 1
	return n, nil
}

func startsStruct(line string, ind int) bool {
	i := indentOf(line)
	if i < ind {
		return true
	}
	t := line[i:]
	if strings.HasPrefix(t, "- ") || t == "-" {
		return i <= ind
	}
	if splitMapKey(t) != nil {
		return i <= ind
	}
	if strings.HasPrefix(t, "? ") || t == "?" {
		return i <= ind
	}
	return false
}

// gatherFlow collects lines until flow brackets/quotes balance. The first
// line's text is given; p.pos points past it.
func (p *yamlParser) gatherFlow(first string, lineNum int) string {
	text := first
	for !flowComplete(text) {
		nl := p.peek()
		if nl == nil {
			break
		}
		p.pos++
		text += "\n" + nl.text
	}
	return text
}

func flowComplete(s string) bool {
	depth := 0
	var q byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q {
				if q == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				q = 0
			} else if q == '"' && c == '\\' {
				i++
			}
			continue
		}
		switch c {
		case '"', '\'':
			q = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > 0 && (s[i-1] == ' ' || s[i-1] == '\n') && depth == 0 {
				return true
			}
		}
	}
	return depth <= 0 && q == 0
}

func blockScalarHeaderIndex(trimmed string) int {
	for i := 0; i < len(trimmed); i++ {
		c := trimmed[i]
		if c == '|' || c == '>' {
			if i == 0 || trimmed[i-1] == ' ' {
				return i
			}
		}
		if c == '#' && i > 0 && trimmed[i-1] == ' ' {
			return -1
		}
	}
	return -1
}

// applyProps parses anchor/tag prefix (e.g. "&a !!str") onto node.
func (p *yamlParser) applyProps(n *Node, prefix string, lineNum int) error {
	fp := &flowParser{s: prefix, line: lineNum, anchors: p.anchors}
	for {
		fp.skipSpace()
		if fp.pos >= len(fp.s) {
			break
		}
		c := fp.s[fp.pos]
		if c == '&' {
			fp.pos++
			name := fp.readAnchorName()
			n.Anchor = name
			fp.anchors[name] = n
		} else if c == '!' {
			tag, err := fp.readTag()
			if err != nil {
				return err
			}
			n.Tag = tag
			n.Style |= TaggedStyle
		} else {
			return yamlErr(lineNum, "did not find expected node content")
		}
	}
	return nil
}

// parseBlockScalar parses | or > content following the header line.
// parentIndent is the enclosing block structure's indent.
func (p *yamlParser) parseBlockScalar(header string, parentIndent int, lineNum int) (*Node, error) {
	style := LiteralStyle
	if header[0] == '>' {
		style = FoldedStyle
	}
	chomp := byte(0)
	explicitIndent := 0
loop:
	for i := 1; i < len(header); i++ {
		c := header[i]
		switch {
		case c == '+' || c == '-':
			chomp = c
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		case c == ' ' || c == '\t':
			break loop
		default:
			return nil, yamlErr(lineNum, "did not find expected comment or line break")
		}
	}
	var lines []string
	blockIndent := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if isBlank(l.text) {
			lines = append(lines, "")
			p.pos++
			continue
		}
		ind := indentOf(l.text)
		if blockIndent == -1 {
			if ind <= parentIndent {
				break
			}
			if explicitIndent > 0 {
				blockIndent = parentIndent + explicitIndent
			} else {
				blockIndent = ind
			}
		}
		if ind < blockIndent {
			break
		}
		lines = append(lines, l.text[blockIndent:])
		p.pos++
	}
	trailing := 0
	for i := len(lines) - 1; i >= 0 && lines[i] == ""; i-- {
		trailing++
	}
	core := strings.Join(lines, "\n")
	core = strings.TrimRight(core, "\n")
	var val string
	if style == LiteralStyle {
		val = core
	} else {
		val = foldBlockLines(strings.Split(core, "\n"))
	}
	switch chomp {
	case '-':
	case '+':
		val += strings.Repeat("\n", trailing+1)
	default:
		val += "\n"
	}
	return &Node{Kind: ScalarNode, Style: style, Tag: "!!str", Value: val}, nil
}

func foldBlockLines(lines []string) string {
	var b strings.Builder
	for i, l := range lines {
		if i > 0 {
			prev := lines[i-1]
			if l == "" || prev == "" {
				b.WriteByte('\n')
			} else {
				b.WriteByte(' ')
			}
		}
		b.WriteString(l)
	}
	return b.String()
}

func stripInlineComment(s string) string {
	r, _ := splitInlineComment(s)
	return r
}

// splitInlineComment splits s at ' #' returning content and comment text.
func splitInlineComment(s string) (string, string) {
	inQ := byte(0)
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQ != 0 {
			if c == inQ {
				if inQ == '\'' && i+1 < len(s) && s[i+1] == '\'' {
					i++
					continue
				}
				inQ = 0
			} else if inQ == '"' && c == '\\' {
				i++
			}
			continue
		}
		switch c {
		case '"', '\'':
			inQ = c
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') && depth == 0 {
				return strings.TrimRight(s[:i-1], " "), strings.TrimSpace(s[i+1:])
			}
		}
	}
	return strings.TrimRight(s, " "), ""
}

