package yq

import (
	"fmt"
	"strings"
)

// YamlEncoder renders nodes back to YAML, preserving style/comments,
// mimicking yq's printer output.
type YamlEncoder struct {
	Opts       *Opts
	buf        strings.Builder
	atLineStart bool
}

// EncodeYAML renders one node (document or bare) to YAML text (no trailing
// doc separator handling; printer adds those).
func EncodeYAML(n *Node, opts *Opts) (string, error) {
	e := &YamlEncoder{Opts: opts, atLineStart: true}
	if n.Kind == DocumentNode {
		e.writeHeadComment(n.HeadComment, 0)
		if len(n.Content) > 0 {
			if err := e.encodeNode(n.Content[0], 0, ctxRoot); err != nil {
				return "", err
			}
		}
	} else {
		if err := e.encodeNode(n, 0, ctxRoot); err != nil {
			return "", err
		}
	}
	out := e.buf.String()
	out = strings.TrimRight(out, "\n")
	if out != "" {
		out += "\n"
	}
	return out, nil
}

type encCtx int

const (
	ctxRoot encCtx = iota
	ctxBlock // block context (map value or seq item)
	ctxFlow  // inside flow collection
)

func (e *YamlEncoder) write(s string) {
	e.buf.WriteString(s)
	if strings.HasSuffix(s, "\n") {
		e.atLineStart = true
	} else if s != "" {
		e.atLineStart = false
	}
}

func (e *YamlEncoder) writeIndent(ind int) {
	e.write(strings.Repeat(" ", ind))
}

// writeCommentLines writes comment lines at given indent, prefixed with '#'.
func writeCommentText(head string) []string {
	if head == "" {
		return nil
	}
	return strings.Split(head, "\n")
}

func (e *YamlEncoder) writeHeadComment(hc string, ind int) {
	for _, line := range writeCommentText(hc) {
		if strings.HasPrefix(line, directiveMarker) {
			e.write(strings.TrimPrefix(line, directiveMarker))
			e.write("\n")
			continue
		}
		if line == "" {
			e.write("\n")
			continue
		}
		e.writeIndent(ind)
		e.write("#")
		if line != "" {
			e.write(" ")
		}
		e.write(line)
		e.write("\n")
	}
}

func (e *YamlEncoder) writeFootComment(fc string, ind int) {
	if fc == "" {
		return
	}
	for _, line := range strings.Split(fc, "\n") {
		if line == "" {
			e.write("\n")
			continue
		}
		e.writeIndent(ind)
		e.write("# " + line)
		e.write("\n")
	}
}

// propsText returns anchor/tag prefix like " &a !!str" for a node.
func propsText(n *Node) string {
	var b strings.Builder
	if n.Anchor != "" {
		b.WriteString("&" + n.Anchor + " ")
	}
	if n.Style&TaggedStyle != 0 && n.Tag != "" {
		b.WriteString(n.Tag + " ")
	}
	return b.String()
}

// encodeNode renders n at indent. Handles scalars, collections, aliases.
func (e *YamlEncoder) encodeNode(n *Node, ind int, ctx encCtx) error {
	switch n.Kind {
	case MappingNode:
		if n.Style&FlowStyle != 0 {
			e.write(e.flowText(n, 0))
			return nil
		}
		if len(n.Content) == 0 {
			e.write("{}")
			return nil
		}
		e.encodeBlockMap(n, ind)
		return nil
	case SequenceNode:
		if n.Style&FlowStyle != 0 {
			e.write(e.flowText(n, 0))
			return nil
		}
		if len(n.Content) == 0 {
			e.write("[]")
			return nil
		}
		e.encodeBlockSeq(n, ind)
		return nil
	case AliasNode:
		e.write("*" + n.Value)
		if n.LineComment != "" {
			e.write(" # " + n.LineComment)
		}
		return nil
	case ScalarNode:
		return e.encodeScalar(n, ind, ctx)
	}
	return nil
}

func (e *YamlEncoder) encodeScalar(n *Node, ind int, ctx encCtx) error {
	style := n.Style
	if style&LiteralStyle != 0 || style&FoldedStyle != 0 {
		e.encodeBlockScalarValue(n, ind)
		return nil
	}
	s := e.scalarText(n, ctx)
	e.write(s)
	if n.LineComment != "" {
		e.write(" # " + n.LineComment)
	}
	return nil
}

// scalarText returns the inline rendering of a scalar node.
func (e *YamlEncoder) scalarText(n *Node, ctx encCtx) string {
	style := n.Style
	if style&SingleQuotedStyle != 0 {
		return "'" + strings.ReplaceAll(n.Value, "'", "''") + "'"
	}
	if style&DoubleQuotedStyle != 0 {
		return doubleQuote(n.Value)
	}
	if n.Tag == "!!str" || n.Tag == "" {
		return e.renderStr(n.Value, ctx)
	}
	// non-string scalars print verbatim
	return n.Value
}

// renderStr decides plain/single/double for a string value.
func (e *YamlEncoder) renderStr(v string, ctx encCtx) string {
	if v == "" {
		return `""`
	}
	// strings that resolve to another type get double quotes
	tag, _ := ResolveScalar(v)
	if tag != "!!str" {
		return doubleQuote(v)
	}
	if isPlainSafe(v, ctx) {
		return v
	}
	if needsDoubleQuoted(v) {
		return doubleQuote(v)
	}
	return "'" + strings.ReplaceAll(v, "'", "''") + "'"
}

// isPlainSafe reports whether v can be emitted as a plain scalar.
func isPlainSafe(v string, ctx encCtx) bool {
	if v == "" {
		return false
	}
	if v != strings.TrimSpace(v) {
		return false // leading/trailing whitespace
	}
	c := v[0]
	switch c {
	case '!', '&', '*', '{', '}', '[', ']', ',', '#', '|', '>', '@', '`', '"', '\'', '%':
		return false
	case '-', '?', ':':
		if len(v) == 1 || v[1] == ' ' {
			return false
		}
	}
	if strings.Contains(v, ": ") || strings.HasSuffix(v, ":") {
		return false
	}
	if strings.Contains(v, " #") {
		return false
	}
	for _, r := range v {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	if strings.ContainsAny(v, "\n") {
		return false
	}
	if ctx == ctxFlow {
		if strings.ContainsAny(v, ",[]{}") {
			return false
		}
	}
	if v == "---" || v == "..." {
		return false
	}
	return true
}

func needsDoubleQuoted(v string) bool {
	for _, r := range v {
		if (r < 0x20 && r != ' ') || r == 0x7f {
			return true
		}
	}
	return strings.ContainsRune(v, '\t')
}

func doubleQuote(v string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range v {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\t':
			b.WriteString(`\t`)
		case '\r':
			b.WriteString(`\r`)
		case '\a':
			b.WriteString(`\a`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\v':
			b.WriteString(`\v`)
		case 0:
			b.WriteString(`\0`)
		case 0x1b:
			b.WriteString(`\e`)
		default:
			if r < 0x20 || r == 0x7f {
				fmt.Fprintf(&b, `\x%02x`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// encodeBlockScalarValue writes | or > content (assumes current position is
// where the header goes; caller writes 'key: ' prefix).
func (e *YamlEncoder) encodeBlockScalarValue(n *Node, ind int) {
	header := "|"
	if n.Style&FoldedStyle != 0 {
		header = ">"
	}
	val := n.Value
	if strings.HasSuffix(val, "\n") {
		trailing := 0
		for i := len(val) - 1; i >= 0 && val[i] == '\n'; i-- {
			trailing++
		}
		if trailing > 1 {
			header += "+"
		}
	} else {
		header += "-"
	}
	e.write(header)
	if n.LineComment != "" {
		e.write(" # " + n.LineComment)
	}
	e.write("\n")
	contentInd := ind + e.Opts.Indent
	lines := strings.Split(strings.TrimRight(val, "\n"), "\n")
	for _, l := range lines {
		if l == "" {
			e.write("\n")
		} else {
			e.writeIndent(contentInd)
			e.write(l)
			e.write("\n")
		}
	}
	if strings.HasSuffix(header, "+") {
		trailing := 0
		for i := len(val) - 1; i >= 0 && val[i] == '\n'; i-- {
			trailing++
		}
		for i := 0; i < trailing-1; i++ {
			e.write("\n")
		}
	}
}

// encodeBlockMap writes mapping entries; each entry starts on a new line at
// indent ind (caller positioned at line start for the first entry).
func (e *YamlEncoder) encodeBlockMap(m *Node, ind int) {
	for i := 0; i < len(m.Content); i += 2 {
		key := m.Content[i]
		val := m.Content[i+1]
		e.writeHeadComment(key.HeadComment, ind)
		e.writeIndent(ind)
		e.write(e.keyText(key))
		valIndented := ind
		compactSeq := e.Opts.CompactSeqIndent
		isColl := val.Kind == MappingNode || val.Kind == SequenceNode
		isFlow := val.Style&FlowStyle != 0
		isEmptyColl := isColl && len(val.Content) == 0
		if val.Kind == ScalarNode && (val.Style&LiteralStyle != 0 || val.Style&FoldedStyle != 0) {
			e.write(": ")
			e.write(propsText(val))
			e.encodeBlockScalarValue(val, ind)
			e.writeFootComment(key.FootComment, ind)
			continue
		}
		if isColl && !isFlow && !isEmptyColl {
			// block collection on following lines
			e.write(":")
			lc := val.LineComment
			if lc == "" {
				lc = key.LineComment
			}
			if lc != "" {
				e.write(" # " + lc)
			}
			if val.Anchor != "" || val.Style&TaggedStyle != 0 {
				e.write(" " + strings.TrimSpace(propsText(val)))
			}
			e.write("\n")
			childInd := ind + e.Opts.Indent
			if val.Kind == SequenceNode && compactSeq {
				childInd = ind
			}
			e.encodeNode(val, childInd, ctxBlock)
			e.writeFootComment(key.FootComment, ind)
			continue
		}
		e.write(": ")
		e.write(propsText(val))
		if isColl {
			e.write(e.flowText(val, 0))
			if val.LineComment != "" {
				e.write(" # " + val.LineComment)
			} else if key.LineComment != "" {
				e.write(" # " + key.LineComment)
			}
		} else {
			e.encodeScalar(val, valIndented, ctxBlock)
			if key.LineComment != "" && val.LineComment == "" && val.Kind != AliasNode {
				e.write(" # " + key.LineComment)
			}
		}
		e.write("\n")
		e.writeFootComment(key.FootComment, ind)
	}
}

// keyText renders a mapping key.
func (e *YamlEncoder) keyText(key *Node) string {
	if key.Kind == ScalarNode {
		return e.scalarText(key, ctxBlock)
	}
	// complex key: flow render (rare)
	return "? " + e.flowText(key, 0)
}

// encodeBlockSeq writes sequence items at indent ind.
func (e *YamlEncoder) encodeBlockSeq(s *Node, ind int) {
	for _, item := range s.Content {
		e.writeHeadComment(item.HeadComment, ind)
		e.writeIndent(ind)
		e.write("-")
		isColl := item.Kind == MappingNode || item.Kind == SequenceNode
		isFlow := item.Style&FlowStyle != 0
		isEmptyColl := isColl && len(item.Content) == 0
		switch {
		case item.Kind == ScalarNode && (item.Style&LiteralStyle != 0 || item.Style&FoldedStyle != 0):
			e.write(" ")
			e.write(propsText(item))
			e.encodeBlockScalarValue(item, ind)
		case isColl && !isFlow && !isEmptyColl:
			if item.Anchor != "" || item.Style&TaggedStyle != 0 {
				e.write(" " + strings.TrimSpace(propsText(item)))
			}
			if item.LineComment != "" {
				e.write(" # " + item.LineComment)
			}
			// nested collection: map entries start right after '- '
			e.write("\n")
			e.encodeNode(item, ind+2, ctxBlock)
			// remove the newline before children trick: encodeNode wrote its own lines
		case isColl:
			e.write(" ")
			e.write(propsText(item))
			e.write(e.flowText(item, 0))
			if item.LineComment != "" {
				e.write(" # " + item.LineComment)
			}
			e.write("\n")
		default:
			e.write(" ")
			e.write(propsText(item))
			e.encodeScalar(item, ind+2, ctxBlock)
			e.write("\n")
		}
		e.writeFootComment(item.FootComment, ind)
	}
}

// flowText renders a node in flow style. depth used for indentation of
// nested flow when pretty? yq renders flow inline always.
func (e *YamlEncoder) flowText(n *Node, depth int) string {
	switch n.Kind {
	case MappingNode:
		if len(n.Content) == 0 {
			return propsText(n) + "{}"
		}
		var parts []string
		for i := 0; i < len(n.Content); i += 2 {
			k := e.flowKeyText(n.Content[i])
			v := e.flowValueText(n.Content[i+1], depth)
			parts = append(parts, k+": "+v)
		}
		return propsText(n) + "{" + strings.Join(parts, ", ") + "}"
	case SequenceNode:
		if len(n.Content) == 0 {
			return propsText(n) + "[]"
		}
		var parts []string
		for _, item := range n.Content {
			parts = append(parts, e.flowValueText(item, depth))
		}
		return propsText(n) + "[" + strings.Join(parts, ", ") + "]"
	case AliasNode:
		return "*" + n.Value
	case ScalarNode:
		return propsText(n) + e.scalarText(n, ctxFlow)
	}
	return ""
}

func (e *YamlEncoder) flowKeyText(n *Node) string {
	if n.Kind == ScalarNode {
		return propsText(n) + e.scalarText(n, ctxFlow)
	}
	return e.flowText(n, 0)
}

func (e *YamlEncoder) flowValueText(n *Node, depth int) string {
	if n.Kind == ScalarNode {
		return propsText(n) + e.scalarText(n, ctxFlow)
	}
	return e.flowText(n, depth)
}
